//! kvhttp: an in-memory HTTP/1.1 key-value server.

mod server;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

use crate::store::KvStore;

fn parse_port(raw: Option<String>) -> Option<u16> {
    raw?.parse().ok().filter(|&port| port != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let Some(port) = parse_port(std::env::args().nth(1)) else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("server error: {err}");
            return ExitCode::FAILURE;
        }
    };
    eprintln!("kvhttp listening on {addr}");

    tokio::select! {
        () = serve(listener, Arc::new(KvStore::new())) => ExitCode::FAILURE,
        () = shutdown_signal() => ExitCode::SUCCESS,
    }
}

/// Accepts connections forever, serving each on its own task.
async fn serve(listener: TcpListener, store: Arc<KvStore>) {
    loop {
        let stream = match listener.accept().await {
            Ok((stream, _)) => stream,
            Err(err) => {
                // Transient failures (e.g. EMFILE) must not bring the server down.
                eprintln!("accept error: {err}");
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                continue;
            }
        };
        let _ = stream.set_nodelay(true);
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| server::handle(Arc::clone(&store), req));
            if let Err(err) = http1::Builder::new()
                .serve_connection(TokioIo::new(stream), service)
                .await
            {
                eprintln!("connection error: {err}");
            }
        });
    }
}

async fn shutdown_signal() {
    use tokio::signal::unix::{SignalKind, signal};
    let (Ok(mut term), Ok(mut int)) = (
        signal(SignalKind::terminate()),
        signal(SignalKind::interrupt()),
    ) else {
        return std::future::pending().await;
    };
    tokio::select! {
        _ = term.recv() => {}
        _ = int.recv() => {}
    }
}

//! HTTP routing and request handling.

use std::convert::Infallible;
use std::sync::Arc;

use bytes::Bytes;
use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::body::{Body, Incoming};
use hyper::header::{ALLOW, CONNECTION, CONTENT_LENGTH, CONTENT_TYPE, HeaderValue};
use hyper::{Method, Request, Response, StatusCode};

use crate::store::KvStore;

/// Largest accepted value, in bytes.
pub const MAX_VALUE_BYTES: usize = 1024 * 1024;
const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LEN: usize = 64;

/// Returns whether `key` matches `[A-Za-z0-9_-]{1,64}`.
fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn send(
    status: StatusCode,
    body: impl Into<Bytes>,
    content_type: Option<&'static str>,
) -> Response<Full<Bytes>> {
    let body = body.into();
    let mut res = Response::new(Full::new(body.clone()));
    *res.status_mut() = status;
    let headers = res.headers_mut();
    headers.insert(CONTENT_LENGTH, HeaderValue::from(body.len()));
    if let Some(ct) = content_type {
        headers.insert(CONTENT_TYPE, HeaderValue::from_static(ct));
    }
    res
}

fn empty(status: StatusCode) -> Response<Full<Bytes>> {
    send(status, Bytes::new(), None)
}

fn method_not_allowed(allowed: &'static str) -> Response<Full<Bytes>> {
    let mut res = empty(StatusCode::METHOD_NOT_ALLOWED);
    res.headers_mut()
        .insert(ALLOW, HeaderValue::from_static(allowed));
    res
}

/// An error response that also closes the connection, since the request body
/// may not have been fully consumed.
fn fatal(status: StatusCode) -> Response<Full<Bytes>> {
    let mut res = empty(status);
    res.headers_mut()
        .insert(CONNECTION, HeaderValue::from_static("close"));
    res
}

/// Reads the request body, rejecting it with `413` if it exceeds `limit` bytes.
async fn read_body(body: Incoming, limit: usize) -> Result<Bytes, StatusCode> {
    if body.size_hint().lower() > limit as u64 {
        return Err(StatusCode::PAYLOAD_TOO_LARGE);
    }
    match Limited::new(body, limit).collect().await {
        Ok(collected) => Ok(collected.to_bytes()),
        Err(err) if err.is::<LengthLimitError>() => Err(StatusCode::PAYLOAD_TOO_LARGE),
        Err(_) => Err(StatusCode::BAD_REQUEST),
    }
}

/// Handles a single request against `store`.
pub async fn handle(
    store: Arc<KvStore>,
    req: Request<Incoming>,
) -> Result<Response<Full<Bytes>>, Infallible> {
    let (parts, body) = req.into_parts();
    let method = parts.method;
    let path = parts.uri.path();

    let res = match path {
        "/health" => match method {
            Method::GET => send(StatusCode::OK, "ok", Some("text/plain; charset=utf-8")),
            _ => method_not_allowed("GET"),
        },
        "/kv" => match method {
            Method::GET => send(
                StatusCode::OK,
                keys_json(&store.keys()),
                Some("application/json"),
            ),
            _ => method_not_allowed("GET"),
        },
        _ => match path.strip_prefix(KV_PREFIX) {
            Some(key) if !is_valid_key(key) => empty(StatusCode::BAD_REQUEST),
            Some(key) => match method {
                Method::GET => match store.get(key) {
                    Some(value) => send(StatusCode::OK, value, Some("application/octet-stream")),
                    None => empty(StatusCode::NOT_FOUND),
                },
                Method::PUT => match read_body(body, MAX_VALUE_BYTES).await {
                    Ok(value) => {
                        let created = store.set(key, value);
                        empty(if created {
                            StatusCode::CREATED
                        } else {
                            StatusCode::OK
                        })
                    }
                    Err(status) => fatal(status),
                },
                Method::DELETE if store.delete(key) => empty(StatusCode::NO_CONTENT),
                Method::DELETE => empty(StatusCode::NOT_FOUND),
                _ => method_not_allowed("GET, PUT, DELETE"),
            },
            None => empty(StatusCode::NOT_FOUND),
        },
    };
    Ok(res)
}

/// Serializes keys as a JSON array. Valid keys never need escaping.
fn keys_json(keys: &[String]) -> String {
    let mut out = String::with_capacity(2 + keys.iter().map(|k| k.len() + 3).sum::<usize>());
    out.push('[');
    for (i, key) in keys.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push('"');
        out.push_str(key);
        out.push('"');
    }
    out.push(']');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
    }

    #[test]
    fn json_keys() {
        assert_eq!(keys_json(&[]), "[]");
        assert_eq!(keys_json(&["a".into(), "b".into()]), r#"["a","b"]"#);
    }
}

//! In-memory key-value store. Values are kept as raw bytes.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

/// A thread-safe map from keys to byte values, ordered by key.
#[derive(Debug, Default)]
pub struct KvStore {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl KvStore {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`; returns `true` if the key was newly created.
    pub fn set(&self, key: &str, value: Bytes) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.insert(key.to_owned(), value).is_none()
    }

    pub fn get(&self, key: &str) -> Option<Bytes> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.get(key).cloned()
    }

    /// Removes `key`; returns `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        let mut entries = self.entries.write().unwrap_or_else(PoisonError::into_inner);
        entries.remove(key).is_some()
    }

    /// All keys in ascending order.
    pub fn keys(&self) -> Vec<String> {
        let entries = self.entries.read().unwrap_or_else(PoisonError::into_inner);
        entries.keys().cloned().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn set_get_delete() {
        let store = KvStore::new();
        assert!(store.set("b", Bytes::from_static(b"1")));
        assert!(!store.set("b", Bytes::from_static(b"2")));
        assert!(store.set("a", Bytes::new()));
        assert_eq!(store.get("b").as_deref(), Some(&b"2"[..]));
        assert_eq!(store.keys(), ["a", "b"]);
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }
}
